package com.bank.maxproduct;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Finds the strongest compounding stretch for National Bank of India.
public class MaxProductAnalyzer {
    private static final Logger log = Logger.getLogger(MaxProductAnalyzer.class.getName());

    // Largest contiguous product. O(n), O(1). Tracks max AND min (negatives flip).
    public BigDecimal bestContiguousProduct(BigDecimal[] factors) {
        if (factors == null || factors.length == 0) {
            throw new IllegalArgumentException("factors must be non-empty");
        }
        BigDecimal maxProduct = factors[0];   // best product ending here
        BigDecimal minProduct = factors[0];   // worst product ending here
        BigDecimal best = factors[0];         // best seen anywhere
        for (int i = 1; i < factors.length; i++) {
            BigDecimal f = factors[i];
            if (f.signum() < 0) {
                BigDecimal tmp = maxProduct;   // negative flips roles
                maxProduct = minProduct;
                minProduct = tmp;
            }
            maxProduct = f.max(maxProduct.multiply(f)); // extend or start fresh
            minProduct = f.min(minProduct.multiply(f));
            if (maxProduct.compareTo(best) > 0) {
                best = maxProduct;             // new best compounding run
            }
        }
        final BigDecimal result = best;
        log.info(() -> "Best product = " + result);
        return best;
    }
}
