package com.bank.maxproduct;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: strongest compounding stretch for Rajesh.
public class MaxProductDemo {
    private static final Logger log = Logger.getLogger(MaxProductDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    private static BigDecimal bd(String s) { return new BigDecimal(s); }

    public static void main(String[] args) {
        MaxProductAnalyzer analyzer = new MaxProductAnalyzer();

        // Rajesh (SAV2001) daily portfolio growth factors.
        BigDecimal[] factors = { bd("2"), bd("3"), bd("-2"), bd("4") };
        BigDecimal product = analyzer.bestContiguousProduct(factors);
        log.info(() -> "Best compounding product for Rajesh = " + product);

        // A run of two negatives flips to a large positive.
        BigDecimal[] flip = { bd("-2"), bd("0"), bd("-1") };
        log.info(() -> "Flip case best = " + analyzer.bestContiguousProduct(flip));
    }
}
